        self.id = id
        self.name = name
        self.profileName = profileName
        self.groupName = groupName
        self.version = version
        self.software = software
        self.port = port
        self.memoryMb = memoryMb
        self.path = path
        self.status = status
        self.javaPath = javaPath
        self.unavailableReason = unavailableReason
